INSERT INTO texts VALUES(89631142,'푸른 눈의 백룡','높은 공격력을 자랑하는 전설의 드래곤. 어떠한 상대라도 분쇄해 버리는 파괴력은 상상을 초월한다.','','','','','','','','','','','','','','','','');
